"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6183],{223:(e,a,t)=>{t.d(a,{$I:()=>o,Af:()=>s,Vy:()=>n});let n={UEI:{term:"UEI",expansion:"Unique Entity ID",plain:"A 12-character code the US government gives your business when you register it on sam.gov, the System for Award Management. It is free. In 2022 it replaced the old DUNS number (Data Universal Numbering System), which a private company used to issue.",soWhat:"No federal grant can pay you without one. Getting it takes a few weeks, so it is worth starting early — we will keep showing you opportunities while you wait."},SAM:{term:"SAM",expansion:"System for Award Management",plain:"The official US government website (sam.gov) where a business registers to be able to receive federal money. Registration is free.",soWhat:"Being registered here is a prerequisite for most federal funding. It is not a judgement of your business — it is paperwork."},TRL:{term:"TRL",expansion:"Technology Readiness Level",plain:'A 1-to-9 scale for how far along a technology is. 1 is "we had an idea and did the maths", 4-6 is "it works in a lab or a test rig", 9 is "it is in service and proven".',soWhat:"Programmes usually say which levels they fund. Early-stage research money will not take a finished product, and scale-up money will not take a sketch — matching the level is often the difference between eligible and not."},SBIR:{term:"SBIR",expansion:"Small Business Innovation Research",plain:"A federal program that pays small US businesses to develop new technology. It runs in phases: a small feasibility award first, a larger development award second.",soWhat:"You keep the intellectual property and you give away no equity. It is one of the largest sources of non-dilutive money for a technical company."},STTR:{term:"STTR",expansion:"Small Business Technology Transfer",plain:"Like SBIR (Small Business Innovation Research), but the work is shared with a university or a non-profit research institution as a formal partner.",soWhat:"Worth looking at if you already work with a lab. The partnership is required, not optional."},NAICS:{term:"NAICS",expansion:"North American Industry Classification System",plain:"The numeric code the US government uses to say what industry a business is in. Most businesses have one main code and a few others.",soWhat:"Some programs are limited to particular codes, and business-size limits are set per code. The right code can make you eligible; the wrong one can hide you."},EIN:{term:"EIN",expansion:"Employer Identification Number",plain:"A nine-digit tax number the Internal Revenue Service (IRS) gives a business, written like 12-3456789. Think of it as a social security number for the company.",soWhat:"Used to identify your business on almost every federal form."},DUNS:{term:"DUNS",expansion:"Data Universal Numbering System",plain:"A nine-digit business ID issued by a private company, Dun & Bradstreet. The US government stopped using it in April 2022.",soWhat:"If you have an old DUNS number it is no longer what the government asks for — the Unique Entity ID (UEI) replaced it. Nothing to do unless an old form asks."},RFP:{term:"RFP",expansion:"Request for Proposal",plain:"A published notice saying an organization wants to buy something specific and is inviting written offers, usually by a deadline.",soWhat:"This is a purchase, not a grant. They pay you to deliver a named thing."},NOFO:{term:"NOFO",expansion:"Notice of Funding Opportunity",plain:"The formal announcement of a grant program: who can apply, what it funds, how much, and by when. It is the rulebook for that opportunity.",soWhat:"When we say an opportunity has published rules, this is the document those rules come from."},DSCR:{term:"DSCR",expansion:"Debt Service Coverage Ratio",plain:"How many times over your cash profit covers your loan repayments. 1.0 means it exactly covers them; 1.25 means you have a quarter left over.",soWhat:"Lenders use it to decide whether a loan is affordable for you. Most want to see comfortably above 1."},"SET-ASIDE":{term:"set-aside",plain:"A portion of funding reserved for a particular kind of business — for example small businesses, or businesses owned by veterans.",soWhat:"If you qualify for one, you compete against a much smaller field. If you do not, you cannot apply at all."},"NON-DILUTIVE":{term:"non-dilutive",plain:"Money you do not give up any ownership of your company to receive. Grants are non-dilutive; selling shares to an investor is not.",soWhat:"You keep 100% of your business."},CCR:{term:"CCR",expansion:"Central Contractor Registration",plain:"The old name for the federal registration a business needed before it could be paid by the US government. It was retired in 2012 and folded into sam.gov.",soWhat:"Some application forms are still headed this way. If a form asks for it, the details it wants are the ones on your sam.gov registration — there is nothing separate to sign up for."},CAGE:{term:"CAGE code",expansion:"Commercial and Government Entity code",plain:"A five-character code that identifies one physical business location to the US government. You do not apply for it separately — it is issued to you when your sam.gov registration goes through.",soWhat:"Forms ask for it alongside your other registration numbers. If your registration is live you already have one."},IRS:{term:"IRS",expansion:"Internal Revenue Service",plain:"The US federal tax authority. It is the office that issues a business its federal tax number and that a company files its tax return with.",soWhat:"It issues the tax number that identifies your business on federal forms."},"SF-424":{term:"SF-424",expansion:"Standard Form 424",plain:"The cover sheet almost every federal grant application starts with: who you are, where you are, what you are asking for and how much.",soWhat:"It is almost entirely facts we already hold about your company, which is why we can fill most of it for you."},"SF-LLL":{term:"SF-LLL",expansion:"Standard Form LLL, Disclosure of Lobbying Activities",plain:"A one-page form that asks whether you paid anyone to lobby a federal official about this award.",soWhat:'For nearly every small company the honest answer is "no", and the form is a signature rather than a task.'},"R&R":{term:"R&R",expansion:"Research and Related",plain:'The family of federal forms used for research awards — a budget form, a senior personnel form and so on. "R&R" on a form name just tells you it belongs to that research set.',soWhat:"It tells you which version of a form a program wants."},SOPO:{term:"SOPO",expansion:"Statement of Project Objectives",plain:"A short, structured description of what you will do, broken into tasks with a result for each. The Department of Energy asks for it by this name.",soWhat:"It becomes the checklist the award is managed against, so keep every task something you can show you finished."},NEPA:{term:"NEPA",expansion:"National Environmental Policy Act",plain:"The US law that requires a federal agency to consider the environmental effects of anything it funds. In practice it arrives as a questionnaire.",soWhat:'For work in a lab or an office the answers are usually "no effect" and it is quick. For anything that breaks ground it is a real piece of work with a real timeline.'},BIOSKETCH:{term:"biosketch",expansion:"biographical sketch",plain:"A short, strictly formatted CV for each senior person on the project — usually a few pages, on the agency's own template.",soWhat:"Health and science agencies reject applications for using the wrong template, so start from the one the notice links to."},BAA:{term:"BAA",expansion:"Broad Agency Announcement",plain:"A standing invitation from a defence or research agency saying which subjects it wants to fund, usually open for a year or more rather than closing on one date.",soWhat:"There is often no fixed deadline, so it is the kind of opportunity you can prepare for properly instead of rushing."},FOA:{term:"FOA",expansion:"Funding Opportunity Announcement",plain:"Another name for the published rules of a grant program: who can apply, what it pays for, how much and by when.",soWhat:"It means the same thing as a Notice of Funding Opportunity. Different agencies use different names for the same document."},CSO:{term:"CSO",expansion:"Commercial Solutions Opening",plain:"A route the Department of Defense uses to buy commercial technology, with a short pitch first instead of a full proposal.",soWhat:"The first step is usually a few pages, so the cost of trying is low."},CFDA:{term:"CFDA number",expansion:"Catalog of Federal Domestic Assistance number",plain:"The catalogue number of a federal assistance program, written like 12.345. It is now officially called the Assistance Listing number, but the old name is still on most forms.",soWhat:"It identifies the program rather than the individual opportunity, and your accountant will need it after an award."},WOSB:{term:"WOSB",expansion:"Woman-Owned Small Business",plain:"A federal designation for a small business that is at least 51% owned and run by women. You certify for it, and the certification is free.",soWhat:"Some contracts are reserved for certified businesses only, so certifying can open a field with far fewer competitors in it."},SDVOSB:{term:"SDVOSB",expansion:"Service-Disabled Veteran-Owned Small Business",plain:"A federal designation for a small business at least 51% owned and run by a veteran with a service-connected disability. It is certified, and the certification is free.",soWhat:"The government sets itself an annual target for spending with these businesses, which is why the reserved contracts exist."},HUBZONE:{term:"HUBZone",expansion:"Historically Underutilized Business Zone",plain:"A federal designation for a small business whose main office sits in a designated area and most of whose staff live in one.",soWhat:"It is decided by your address, so it is worth checking even if none of the other designations fit you."},FTE:{term:"FTE",expansion:"full-time equivalent",plain:"A way of counting staff by hours rather than heads. One person working full time is 1.0; two people at half time are also 1.0.",soWhat:"Budget forms ask for effort this way, so a part-time founder is a fraction, not a whole person."},"G&A":{term:"G&A",expansion:"general and administrative cost",plain:"The cost of running the business that is not tied to one project — rent, insurance, bookkeeping. It is charged to a project as a percentage.",soWhat:"Leaving it out of a budget means the award pays for the work but not for the company doing it."},ODC:{term:"ODC",expansion:"other direct cost",plain:"Project costs that are neither wages nor overhead — materials, travel, a piece of test equipment, a subcontractor invoice.",soWhat:"It is the budget line where anything you had to buy belongs."},CPFF:{term:"CPFF",expansion:"cost plus fixed fee",plain:"A contract that pays back what the work actually cost, plus an agreed profit that does not change if the cost does.",soWhat:"Your profit is fixed in advance, so spending more does not earn you more — and it means you must be able to account for every cost."},ROI:{term:"ROI",expansion:"return on investment",plain:"What you get back compared with what you put in, usually written as a percentage. Putting in 100 and getting back 130 is a 30% return."},PI:{term:"PI",expansion:"principal investigator",plain:"The named person who is responsible for the work and answerable to the funder for it. On a small company application this is usually the technical founder.",soWhat:"Some programs set rules about the principal investigator — that they must be employed by you, or work a minimum share of their time on the project."},IRB:{term:"IRB",expansion:"Institutional Review Board",plain:"The committee that must approve any research involving people before it starts.",soWhat:"If your work touches human participants or their data, approval takes weeks and the application will ask whether you have it."},IP:{term:"IP",expansion:"intellectual property",plain:"What you own of the ideas themselves — patents, software copyright, trade secrets, designs.",soWhat:"Federal research awards generally let you keep yours, which is the main reason they are worth applying for."},CRADA:{term:"CRADA",expansion:"Cooperative Research and Development Agreement",plain:"A formal agreement to do research jointly with a federal laboratory. No money changes hands — each side contributes people, equipment or facilities.",soWhat:"It buys access to instruments and expertise a small company could never afford, in exchange for sharing results."},SBA:{term:"SBA",expansion:"Small Business Administration",plain:"The federal agency for small businesses. It guarantees loans, runs counselling services, and sets the size limits that decide who counts as small.",soWhat:"Its size rules decide whether you can apply for a great deal of federal funding, and its loan guarantees are why a bank will lend to a company it would otherwise refuse."},DOD:{term:"DoD",expansion:"Department of Defense",plain:"The US military. It is the largest federal buyer of new technology and the largest single source of research awards to small companies."},NIH:{term:"NIH",expansion:"National Institutes of Health",plain:"The federal agency that funds medical and biological research. It is made up of institutes, each funding its own field, so a single notice usually comes from one of them rather than from the whole agency."},NSF:{term:"NSF",expansion:"National Science Foundation",plain:"The federal agency that funds science and engineering research outside medicine, in universities and in small companies."},DOE:{term:"DOE",expansion:"Department of Energy",plain:"The federal agency for energy research. It runs the national laboratories and funds work on power, fuels, efficiency and grid technology."},EPA:{term:"EPA",expansion:"Environmental Protection Agency",plain:"The federal agency that writes and enforces environmental rules, and that funds research into cleaner technology."},USDA:{term:"USDA",expansion:"Department of Agriculture",plain:"The federal agency for farming, food and rural areas. It also lends and guarantees loans to rural businesses of any kind."},DHS:{term:"DHS",expansion:"Department of Homeland Security",plain:"The federal agency responsible for borders, airports, disaster response and federal cyber security. It buys technology for all four."},NASA:{term:"NASA",expansion:"National Aeronautics and Space Administration",plain:"The federal agency for space exploration and for aircraft research. It buys a great deal of what it flies from private companies."},DARPA:{term:"DARPA",expansion:"Defense Advanced Research Projects Agency",plain:"The Department of Defense unit that funds high-risk, far-ahead research. Programmes are run by individual managers for a few years each.",soWhat:"It expects ambition and accepts failure, which makes it unlike most funders."},IARPA:{term:"IARPA",expansion:"Intelligence Advanced Research Projects Activity",plain:"The intelligence agencies' own funder of high-risk, far-ahead research, run in the same style as the Defense Advanced Research Projects Agency."},ONR:{term:"ONR",expansion:"Office of Naval Research",plain:"The US Navy's own research funding office. It pays for research in universities and companies as well as in its own laboratories."},AFRL:{term:"AFRL",expansion:"Air Force Research Laboratory",plain:"The US Air Force's own research organization. It runs laboratories and it funds research in companies and universities."},AFWERX:{term:"AFWERX",expansion:"the Air Force innovation office",plain:"The Air Force unit set up to buy from small and non-traditional companies quickly, with shorter applications than the usual route."},SOCOM:{term:"SOCOM",expansion:"US Special Operations Command",plain:"The military command for special operations forces. It buys its own equipment, on a faster timeline than the rest of the Department of Defense."},EDA:{term:"EDA",expansion:"Economic Development Administration",plain:"The federal agency that funds job creation and infrastructure in particular regions.",soWhat:"Its money is tied to places, so whether you qualify depends largely on where you are."},CDMRP:{term:"CDMRP",expansion:"Congressionally Directed Medical Research Programs",plain:"A Department of Defense program that funds medical research on the specific conditions Congress names each year, such as particular cancers."},"ARPA-H":{term:"ARPA-H",expansion:"Advanced Research Projects Agency for Health",plain:"A health research funder created in 2022 for ambitious, fast-moving projects, modelled on the defence research agency."},DIU:{term:"DIU",expansion:"Defense Innovation Unit",plain:"The Department of Defense office that buys existing commercial technology for military use, on a commercial timeline.",soWhat:"It wants products that already work, not research proposals."},CDFI:{term:"CDFI",expansion:"Community Development Financial Institution",plain:"A certified lender whose job is to serve businesses and places that ordinary banks turn down. They are real lenders, not charities.",soWhat:"If a bank has said no, this is usually the next door, and the terms are often better than anything else available to you."},CFR:{term:"CFR",expansion:"Code of Federal Regulations",plain:'The published rulebook of the US federal government. A citation like "2 CFR 200.403" points at one numbered rule in it.',soWhat:"When we say a rule comes from somewhere, this is the kind of address we give, so you or your accountant can read the rule itself."},USC:{term:"USC",expansion:"United States Code",plain:'The collected federal laws passed by Congress. A citation like "10 USC 4022" points at one numbered section of it.',soWhat:'A law outranks an agency\'s own guidance, so a citation of this kind is the strongest answer to "says who?".'},QA:{term:"QA",expansion:"quality assurance",plain:"Quality assurance: the checking that makes sure work meets the standard it was meant to meet, before anyone else sees it."},ZIP:{term:"ZIP code",expansion:"Zone Improvement Plan code",plain:"The US postal code for an address, five digits, written like 78701. It is the narrowest piece of geography most forms ask for.",soWhat:"Several programs are drawn on a map, so your postal code alone can decide whether you qualify."},LLC:{term:"LLC",expansion:"Limited Liability Company",plain:"A common US way of registering a business. The owners are not personally on the hook for the company's debts, and profits are normally taxed as the owners' income rather than the company's."},"ENTITY-TYPE":{term:"entity type",plain:"The legal form your company was registered as, such as a Limited Liability Company (LLC), a C-corporation, a nonprofit or a sole proprietor. It is on your formation paperwork.",soWhat:'It is a hard gate on most funding. A program open only to nonprofits is closed to a company, and the other way round, so we never guess it. If none of the choices fit, pick "Other / not sure" and we assume nothing about you.'},STAGE:{term:"stage",plain:"Roughly how far along the company is: Seed before there is revenue, Early at the first customers, Growth while revenue is climbing, Established once things are steady.",soWhat:"Some programs are aimed only at companies at a particular point. Whichever band is closest is right. It is a rough description, not an audited fact, and nothing here is checked against your accounts."},STATE:{term:"state",plain:"The US state or territory the company is based in, stored as its two-letter postal code.",soWhat:"A great deal of funding is limited to one state or one region, and there are programs that exist only in yours. It is also how we work out whether your address sits in a specially designated area."},COUNTRY:{term:"country",plain:"The country the company is based in, stored as the standard two-letter country code.",soWhat:"Most federal programs require a US-based applicant, so this decides whether those show up for you at all."},"ALERTS-EMAIL":{term:"alerts email",plain:"The address we send deadline reminders and new-match alerts to. Leave it empty and they go to the address you sign in with.",soWhat:"Worth setting if the person who watches deadlines is not the person who signed up. It is never shown to a funder and never used for anything else."},"WHAT-YOU-DO":{term:"what you do",plain:"A few sentences describing what the company actually makes or does, in your own words.",soWhat:'Every word of it is matched against the text of live funding notices, which is why plain sentences beat a list of buzzwords: "we machine titanium brackets for satellite structures" finds far more than "manufacturing" does.'},"NET-INCOME":{term:"net income",plain:"What the business earned after every expense, for the most recent year you have filed. A loss is a real answer and is worth entering — it is a fact about one year, not a verdict.",soWhat:"It is the figure a lender divides by the loan repayment to see whether the payment is affordable. Nothing else on your profile can answer that question."},"MONTHLY-DEBT-PAYMENTS":{term:"monthly debt payments",plain:"What the business already pays each month on loans, lines of credit and finance agreements it has taken out. Enter 0 if it has none — that is a real answer, not a blank.",soWhat:"A lender adds a new payment on top of these, so the total is what decides whether an amount is affordable. Left blank we have to say we do not know, which is the honest answer and not a useful one."},"CREDIT-RANGE":{term:"credit range",plain:"Roughly where the main owner’s personal credit score sits, chosen as a range rather than an exact number. You tell us; nothing is checked, requested or looked up, and no enquiry is created anywhere.",soWhat:"Most business loan programs publish a minimum, so this is often the single fact that decides which ones are worth your time. Leaving it blank never counts against you — the row simply says we were not told."},COLLATERAL:{term:"collateral",plain:"Things the business owns that a lender could take security over if the loan were not repaid — vehicles, equipment, stock, property. Describing them is not offering them.",soWhat:"Above roughly fifty thousand dollars most lenders ask what is available, and they do not require it to cover the whole loan. Saying what you have stops the row reporting an unknown."}};function o(e){return n[e.trim().toUpperCase().replace(/\s+/g,"-")]}let s=Object.keys(n)},6183:(e,a,t)=>{t.d(a,{A:()=>i});var n=t(5155),o=t(2115),s=t(223);function i({term:e,label:a}){let t=(0,s.$I)(e),[r,l]=(0,o.useState)(!1),h=(0,o.useId)(),c=(0,o.useRef)(null);return((0,o.useEffect)(()=>{if(r)return document.addEventListener("keydown",e),document.addEventListener("mousedown",a),()=>{document.removeEventListener("keydown",e),document.removeEventListener("mousedown",a)};function e(e){"Escape"===e.key&&l(!1)}function a(e){c.current&&!c.current.contains(e.target)&&l(!1)}},[r]),t)?(0,n.jsxs)("span",{className:"relative inline-flex items-baseline gap-1",ref:c,children:[(0,n.jsx)("span",{children:a??t.term}),(0,n.jsx)("button",{type:"button","data-testid":`explain-${t.term.toUpperCase()}`,"aria-expanded":r,"aria-controls":r?h:void 0,"aria-label":`What is ${t.term}?`,onClick:()=>l(e=>!e),className:"explain-trigger",children:"?"}),r&&(0,n.jsxs)("span",{id:h,role:"dialog","aria-label":`${t.term}${t.expansion?` — ${t.expansion}`:""}`,className:"explain-tip",children:[(0,n.jsxs)("span",{className:"explain-tip__title",children:[t.term,t.expansion?` \xb7 ${t.expansion}`:""]}),(0,n.jsx)("span",{className:"explain-tip__body",children:t.plain}),t.soWhat&&(0,n.jsx)("span",{className:"explain-tip__note",children:t.soWhat})]})]}):(0,n.jsx)(n.Fragment,{children:a??e})}}}]);